// API configuration that works both standalone and in production

const getApiBaseUrl = (): string => {
  // Check if we're running in the ESP ecosystem (production)
  if (window.location.pathname.startsWith('/esp-organizer')) {
    return '/esp-organizer-api';
  }

  // Check if we're on skillsfirst.info domain
  if (window.location.hostname === 'skillsfirst.info' || window.location.hostname === 'www.skillsfirst.info') {
    return '/esp-organizer-api';
  }

  // Development mode - USE PROXY (relative path)
  if (process.env.NODE_ENV === 'development') {
    return 'http://localhost:8080'; // ← DIRECT connection
  }

  // Standalone development mode (fallback)
  const API_URL = process.env.REACT_APP_API_URL;
  if (API_URL) {
    return API_URL;
  }

  // Default fallback for standalone development
  return ''; // ← EMPTY STRING for proxy!
};

export const API_BASE_URL = getApiBaseUrl();

// API client configuration

// Base API URL - configurable for different environments
// This is the main issue - we need to use API_BASE_URL for consistency
const BASE_URL = API_BASE_URL;  // Use the result from getApiBaseUrl instead of redefining

// API endpoints definition
export const API_ENDPOINTS = {
  // Semantic search endpoints
  skills: {
    semanticQuery: '/api/skills/semantic-query',
  },

  // AI chat endpoints
  ai: {
    chat: '/api/ai/chat',
  },

  // Study area specific endpoints
  studyAreas: {
    immunology: {
      search: '/api/immunology/search',
      upload: '/api/immunology/upload-chapter',
      uploadReal: '/api/immunology/upload-chapter-real',
    },
    gcse: {
      search: '/api/gcse/search',
    },
    civilEngineering: {
      search: '/api/civil-engineering/search',
    }
  },

  // Immunology content endpoints
  immunology: {
    chapters: '/api/immunology/chapters',
    caseStudies: '/api/immunology/case-studies',
    medicalTerms: '/api/immunology/medical-terms',
  },

  // Source management
  sources: '/api/sources',

  // Document extraction
  extraction: {
    upload: '/api/extraction/upload',
    status: (jobId: string) => `/api/extraction/status/${jobId}`,
  },
};

// Simplified API client that handles both absolute and relative URLs
export const apiClient = {
  get: async (endpoint: string, params: Record<string, any> = {}) => {
    // Build the URL safely
    let url = BASE_URL + endpoint;

    // Add query parameters if provided
    if (Object.keys(params).length > 0) {
      const searchParams = new URLSearchParams();
      Object.keys(params).forEach(key => {
        searchParams.append(key, String(params[key]));
      });
      url += '?' + searchParams.toString();
    }

    console.log('Making GET request to:', url);

    try {
      const response = await fetch(url, {
        method: 'GET',
        headers: {
          'Accept': 'application/json',
        },
      });

      console.log('Response status:', response.status);
      console.log('Response content type:', response.headers.get('content-type'));

      if (!response.ok) {
        throw new Error(`API error: ${response.status} ${response.statusText}`);
      }

      return await response.json();
    } catch (error) {
      console.error('API GET request failed:', error);
      throw error;
    }
  },

  post: async (endpoint: string, data = {}) => {
    const url = BASE_URL + endpoint;
    console.log('Making POST request to:', url);
    console.log('Request data:', data);

    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        body: JSON.stringify(data),
      });

      console.log('Response status:', response.status);

      if (!response.ok) {
        throw new Error(`API error: ${response.status} ${response.statusText}`);
      }

      return await response.json();
    } catch (error) {
      console.error('API POST request failed:', error);
      throw error;
    }
  },

  // Fix the upload method to include proper headers and error handling
  upload: async (endpoint: string, formData: FormData) => {
    const url = BASE_URL + endpoint;
    console.log('Making file upload request to:', url);
    console.log('FormData contents:', Array.from(formData.entries()).map(([key, value]) => 
      typeof value === 'string' ? `${key}: ${value}` : `${key}: [File or Blob]`));

    try {
      const response = await fetch(url, {
        method: 'POST',
        // Don't set Content-Type header, let the browser set it with boundary
        headers: {
          'Accept': 'application/json',
        },
        body: formData,
      });

      console.log('Response status:', response.status);

      // Handle different response types
      const contentType = response.headers.get('content-type');
      console.log('Response content type:', contentType);

      if (!response.ok) {
        let errorMessage = `API error: ${response.status} ${response.statusText}`;

        // Try to parse error message from JSON response
        if (contentType && contentType.includes('application/json')) {
          const errorData = await response.json();
          errorMessage = errorData.error || errorData.message || errorMessage;
        } else {
          // Read error as text if not JSON
          const textError = await response.text();
          if (textError) errorMessage += ` - ${textError}`;
        }

        throw new Error(errorMessage);
      }

      // Handle successful response
      if (contentType && contentType.includes('application/json')) {
        return await response.json();
      } else {
        return { message: await response.text() };
      }
    } catch (error) {
      console.error('API upload request failed:', error);
      throw error;
    }
  },
};

// Add debug logging to help diagnose routing issues
export const debugRouting = () => {
  console.log('============ ROUTING DEBUG INFO ============');
  console.log('Current location:', window.location.href);
  console.log('Frontend server expected at: http://localhost:3000');
  console.log('API server expected at:', BASE_URL);
  console.log('Current pathname:', window.location.pathname);
  console.log('============================================');
};

// Update console.log to include more debugging info
console.log('API Configuration:', {
  baseUrl: API_BASE_URL,
  environment: process.env.NODE_ENV,
  isESPEcosystem: window.location.pathname.startsWith('/esp-organizer'),
  hostname: window.location.hostname,
  currentUrl: window.location.href,
  currentPathname: window.location.pathname,
  isProduction: API_BASE_URL.startsWith('/esp-organizer-api'),
});
